import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageStudents() {
  const [students, setStudents] = useState([]);
  const [availableSubjects, setAvailableSubjects] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  
  const [formData, setFormData] = useState({ name: '', username: '', grade: 'Grade 10', subjects: '', phone_number: '', email: '', address: '', password: 'ST@123' });
  
  // 🚨 Validation Errors මතක තබා ගන්නා State එක
  const [errors, setErrors] = useState({});

  const fetchStudents = () => axios.get('http://localhost:8082/api/view-students').then(res => setStudents(res.data));
  const fetchSubjects = () => axios.get('http://localhost:8082/api/view-subjects').then(res => setAvailableSubjects(res.data));

  useEffect(() => { fetchStudents(); fetchSubjects(); }, []);

  // 🟢 ශිෂ්‍යයාගේ දත්ත පරික්ශා කරන වැලිඩේෂන් සෙක්ෂන් එක
  const validateForm = () => {
    let formErrors = {};

    // 1. ශිෂ්‍යයාගේ නම
    if (!formData.name.trim()) {
      formErrors.name = "Student's full name is required!";
    }

    // 2. Username සහ Password (අලුතින් ඇතුළත් කරද්දී පමණි)
    if (!isEditing) {
      if (!formData.username.trim()) formErrors.username = "Login username is required!";
      if (!formData.password.trim()) {
        formErrors.password = "Password is required!";
      } else if (formData.password.length < 6) {
        formErrors.password = "Password must be at least 6 characters long!";
      }
      
      // 3. විෂයන් අවම එකක්වත් තෝරාගෙන තිබේදැයි බැලීම
      if (!formData.subjects) {
        formErrors.subjects = "Please select at least one course/subject for enrollment!";
      }
    }

    // 4. ශ්‍රේණිය (Grade)
    if (!formData.grade.trim()) {
      formErrors.grade = "Grade level specification is required!";
    }

    // 5. 📱 Sri Lankan 10-Digit Mobile Phone Validation
    // මැද ඇති හිස්තැන් (Spaces) සහ Dashes ඉවත් කර පිරිසිදු කරයි
    const cleanPhone = formData.phone_number.replace(/[\s\-]/g, '');
    const phoneRegex = /^07[01245678][0-9]{7}$/;
    
    if (!formData.phone_number.trim()) {
      formErrors.phone_number = "Contact number is required!";
    } else if (!phoneRegex.test(cleanPhone)) {
      formErrors.phone_number = "Invalid number! Must be exactly 10 digits starting with 070, 071, 072, 074, 075, 076, 077, or 078.";
    }

    // 6. 📧 Strict Lowercase Email Validation
    const emailRegex = /^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/;
    if (!formData.email.trim()) {
      formErrors.email = "Student email address is required!";
    } else if (/[A-Z]/.test(formData.email)) {
      // කැපිටල් අකුරු ඇතුළත් වුවහොත් එරර් එකක් පෙන්වයි
      formErrors.email = "Email must be in lowercase (simple) letters only!";
    } else if (!emailRegex.test(formData.email)) {
      formErrors.email = "Invalid email format! Provide a proper address (e.g. student@gmail.com).";
    }

    // 7. ලිපිනය
    if (!formData.address.trim()) {
      formErrors.address = "Home address location is required!";
    }

    setErrors(formErrors);
    return Object.keys(formErrors).length === 0;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    
    if (!validateForm()) return;

    const apiPath = isEditing ? `http://localhost:8082/api/update-student/${editId}` : 'http://localhost:8082/api/add-student';
    const method = isEditing ? axios.put : axios.post;

    method(apiPath, formData).then((res) => { 
        if(res.data.status === "Error") alert("Error: " + res.data.error);
        else { fetchStudents(); resetForm(); }
    }).catch(() => alert("Error!"));
  };

  const handleEdit = (s) => {
    setIsEditing(true); setEditId(s.id);
    setFormData({ name: s.name, grade: s.grade, subjects: s.subjects || '', phone_number: s.phone_number, email: s.email || '', address: s.address || '', username: '', password: '' });
    setErrors({});
    setShowForm(true);
  };

  const handleDelete = (id) => {
    if (window.confirm("Are you sure you want to delete this student?")) {
      axios.delete(`http://localhost:8082/api/delete-student/${id}`).then(() => fetchStudents());
    }
  };

  const resetForm = () => { 
    setShowForm(false); 
    setIsEditing(false); 
    setEditId(null); 
    setErrors({}); 
    setFormData({ name: '', username: '', grade: 'Grade 10', subjects: '', phone_number: '', email: '', address: '', password: 'ST@123' }); 
  };

  const filteredStudents = students.filter(s => (s.name || '').toLowerCase().includes(searchQuery.toLowerCase()));

  return (
    <div style={{ padding: '30px', fontFamily: 'sans-serif', backgroundColor: '#f8fafc', minHeight: '100vh' }}>
      <div style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '12px', boxShadow: '0 2px 10px rgba(0,0,0,0.05)' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h2 style={{ margin: 0, color: '#1e293b', fontSize: '20px', display: 'flex', alignItems: 'center', gap: '10px' }}>👨‍🎓 Manage Students</h2>
          <div style={{ display: 'flex', gap: '15px' }}>
            <input type="text" placeholder="Search Student..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} style={styles.searchInput} />
            <button onClick={() => {resetForm(); setShowForm(true);}} style={styles.primaryBtn}>+ Register Student</button>
          </div>
        </div>

        <table style={{ width: '100%', marginTop: '20px', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead>
            <tr style={{ borderBottom: '2px solid #e2e8f0' }}>
              <th style={styles.th}>No.</th>
              <th style={styles.th}>Full Name</th>
              <th style={styles.th}>Grade</th>
              <th style={styles.th}>Enrolled Subjects</th>
              <th style={styles.th}>Phone Number</th>
              <th style={styles.th}>Email</th>
              <th style={styles.th}>Address</th>
              <th style={styles.th}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {[...filteredStudents].sort((a, b) => b.id - a.id).map((s, index) => (
              <tr key={s.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                <td style={styles.td}>{filteredStudents.length - index}</td>
                <td style={{...styles.td, fontWeight: 'bold', color: '#15803d'}}>{s.name}</td>
                <td style={{...styles.td, color: '#64748b', fontSize: '13px'}}>{s.grade}</td>
                <td style={{...styles.td, color: '#0369a1', fontSize: '13px'}}>{s.subjects || '-'}</td>
                <td style={styles.td}>{s.phone_number}</td>
                <td style={{...styles.td, color: '#475569', fontSize: '13px'}}>{s.email || 'No Email'}</td>
                <td style={{...styles.td, color: '#475569'}}>{s.address || 'No Address'}</td>
                <td style={styles.td}>
                  <button onClick={() => handleEdit(s)} style={styles.iconBtn}>✏️</button>
                  <button onClick={() => handleDelete(s.id)} style={styles.iconBtn}>🗑️</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {showForm && (
        <div style={styles.modalOverlay}>
          <div style={styles.modal}>
            <h3 style={{ margin: '0 0 20px 0', color: '#1e293b' }}>{isEditing ? '✏️ Edit Student Profile' : '➕ Physical Student Registration'}</h3>
            
            <form onSubmit={handleSubmit} noValidate style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              
              {/* Name Block */}
              <div style={styles.inputWrapper}>
                <input type="text" placeholder="Student Full Name" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} style={{...styles.input, border: errors.name ? '1px solid #dc2626' : '1px solid #cbd5e1'}} />
                {errors.name && <span style={styles.errorText}>⚠️ {errors.name}</span>}
              </div>
              
              {/* Credentials Grid Block (Add Mode Only) */}
              {!isEditing && (
                <div style={{ display: 'flex', gap: '10px' }}>
                  <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '4px' }}>
                    <input type="text" placeholder="Login Username" value={formData.username} onChange={e => setFormData({...formData, username: e.target.value})} style={{...styles.input, border: errors.username ? '1px solid #dc2626' : '1px solid #cbd5e1'}} />
                    {errors.username && <span style={styles.errorText}>⚠️ {errors.username}</span>}
                  </div>
                  <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '4px' }}>
                    <input type="text" placeholder="Password" value={formData.password} onChange={e => setFormData({...formData, password: e.target.value})} style={{...styles.input, border: errors.password ? '1px solid #dc2626' : '1px solid #cbd5e1'}} />
                    {errors.password && <span style={styles.errorText}>⚠️ {errors.password}</span>}
                  </div>
                </div>
              )}
              
              {/* Grade Block */}
              <div style={styles.inputWrapper}>
                <input type="text" placeholder="Grade level (e.g., Grade 10)" value={formData.grade} onChange={e => setFormData({...formData, grade: e.target.value})} style={{...styles.input, border: errors.grade ? '1px solid #dc2626' : '1px solid #cbd5e1'}} />
                {errors.grade && <span style={styles.errorText}>⚠️ {errors.grade}</span>}
              </div>
              
              {/* Enrolled Subjects Checkboxes Block */}
              {!isEditing && (
                <div style={{ padding: '10px', border: errors.subjects ? '1px solid #dc2626' : '1px solid #cbd5e1', borderRadius: '8px', backgroundColor: '#f8fafc' }}>
                  <p style={{ margin: '0 0 5px 0', fontSize: '13px', color: '#64748b', fontWeight: 'bold' }}>Select Course Enrollment:</p>
                  <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
                    {availableSubjects.map(sub => (
                      <label key={sub.id} style={{ fontSize: '13px', color: '#333', cursor: 'pointer' }}>
                        <input type="checkbox" onChange={(e) => {
                            let curr = formData.subjects ? formData.subjects.split(', ') : [];
                            if(e.target.checked) curr.push(sub.subject_name);
                            else curr = curr.filter(x => x !== sub.subject_name);
                            setFormData({...formData, subjects: curr.join(', ')});
                          }}
                          style={{ accentColor: '#15803d', cursor: 'pointer' }}
                        /> {sub.subject_name}
                      </label>
                    ))}
                  </div>
                  {errors.subjects && <span style={{...styles.errorText, marginTop: '5px'}}>⚠️ {errors.subjects}</span>}
                </div>
              )}
              
              {/* Phone and Email Grid Blocks */}
              <div style={{ display: 'flex', gap: '10px' }}>
                <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '4px' }}>
                  <input type="text" placeholder="Contact Number" value={formData.phone_number} onChange={e => setFormData({...formData, phone_number: e.target.value})} style={{...styles.input, border: errors.phone_number ? '1px solid #dc2626' : '1px solid #cbd5e1'}} />
                  {errors.phone_number && <span style={styles.errorText}>⚠️ {errors.phone_number}</span>}
                </div>
                
                <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '4px' }}>
                  <input type="text" placeholder="Student Email Address" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} style={{...styles.input, border: errors.email ? '1px solid #dc2626' : '1px solid #cbd5e1'}} />
                  {errors.email && <span style={styles.errorText}>⚠️ {errors.email}</span>}
                </div>
              </div>

              {/* Address Block */}
              <div style={styles.inputWrapper}>
                <input type="text" placeholder="Home Address Location" value={formData.address} onChange={e => setFormData({...formData, address: e.target.value})} style={{...styles.input, border: errors.address ? '1px solid #dc2626' : '1px solid #cbd5e1'}} />
                {errors.address && <span style={styles.errorText}>⚠️ {errors.address}</span>}
              </div>
              
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '10px' }}>
                <button type="button" onClick={resetForm} style={styles.cancelBtn}>Cancel</button>
                <button type="submit" style={styles.saveBtn}>{isEditing ? 'Update Details' : 'Register Student'}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

const styles = {
  searchInput: { padding: '8px 15px', borderRadius: '20px', border: '1px solid #cbd5e1', outline: 'none', width: '220px', fontSize: '13px', backgroundColor: '#f8fafc' },
  primaryBtn: { padding: '8px 15px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' },
  th: { padding: '12px 10px', color: '#64748b', fontWeight: 'bold', fontSize: '13px' },
  td: { padding: '15px 10px', fontSize: '14px', verticalAlign: 'top' },
  iconBtn: { background: 'none', border: 'none', cursor: 'pointer', fontSize: '16px', marginRight: '10px' },
  modalOverlay: { position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 },
  modal: { backgroundColor: 'white', padding: '30px', borderRadius: '15px', width: '540px', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)' },
  input: { padding: '10px 15px', borderRadius: '8px', width: '100%', boxSizing: 'border-box', outline: 'none', fontSize: '13px', backgroundColor: '#f8fafc', transition: 'all 0.2s' },
  cancelBtn: { padding: '10px 20px', background: 'none', color: '#64748b', border: 'none', cursor: 'pointer', fontWeight: 'bold', fontSize: '14px' },
  saveBtn: { padding: '10px 20px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '14px' },
  inputWrapper: { display: 'flex', flexDirection: 'column', gap: '4px', width: '100%' },
  errorText: { color: '#dc2626', fontSize: '11px', fontWeight: '500', marginTop: '1px', display: 'block', textAlign: 'left' }
};
